import{_ as e,o as s,c as l,ak as n}from"./chunks/framework.D8TdBi6N.js";const f=JSON.parse('{"title":"编译阶段","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/compilation-phases.md","filePath":"zh/reference/compilation-phases.md","lastUpdated":1782618872000}'),i={name:"zh/reference/compilation-phases.md"};function o(c,a,t,d,r,p){return s(),l("div",null,[...a[0]||(a[0]=[n(`<h1 id="编译阶段" tabindex="-1">编译阶段 <a class="header-anchor" href="#编译阶段" aria-label="Permalink to “编译阶段”">​</a></h1><p>BON 解析器按以下七个阶段处理源文件：</p><h2 id="阶段-0-参数注入" tabindex="-1">阶段 0：参数注入 <a class="header-anchor" href="#阶段-0-参数注入" aria-label="Permalink to “阶段 0：参数注入”">​</a></h2><p>接收 CLI 或 API 传入的 <code>$</code> 变量字典。</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes vitesse-light vitesse-dark" style="background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee;" tabindex="0"><code><span class="line"><span>load(&quot;config.bon&quot;, params={&quot;env&quot;: &quot;prod&quot;, &quot;debug&quot;: True})</span></span>
<span class="line"><span></span></span></code></pre></div><h2 id="阶段-1-词法-语法分析" tabindex="-1">阶段 1：词法/语法分析 <a class="header-anchor" href="#阶段-1-词法-语法分析" aria-label="Permalink to “阶段 1：词法/语法分析”">​</a></h2><ul><li>识别并跳过注释</li><li>构建包含 <code>$</code>、<code>if</code>、<code>for</code> 节点的抽象语法树（AST）</li><li>收集所有顶层模板定义、类定义和变量定义</li></ul><h2 id="阶段-2-导入解析" tabindex="-1">阶段 2：导入解析 <a class="header-anchor" href="#阶段-2-导入解析" aria-label="Permalink to “阶段 2：导入解析”">​</a></h2><ul><li>递归加载所有 <code>import</code> 文件</li><li>合并命名空间，检测循环依赖</li></ul><h2 id="阶段-3-符号解析" tabindex="-1">阶段 3：符号解析 <a class="header-anchor" href="#阶段-3-符号解析" aria-label="Permalink to “阶段 3：符号解析”">​</a></h2><ul><li>检查所有 <code>$</code> 变量是否均已传入</li><li>若缺失，报错中止（<code>E009</code>）</li></ul><h2 id="阶段-4-控制流展开" tabindex="-1">阶段 4：控制流展开 <a class="header-anchor" href="#阶段-4-控制流展开" aria-label="Permalink to “阶段 4：控制流展开”">​</a></h2><ul><li>优先处理<strong>条件（<code>if</code>）</strong>：根据 truthiness 判定剪除不满足条件的分支</li><li>其次处理<strong>循环（<code>for</code>）</strong>：将循环体深拷贝展开为平铺的数据节点</li><li>如果循环体内包含 <code>if</code>，在展开过程中递归处理</li><li>迭代次数超过 10000 时报错中止（<code>E010</code>）</li></ul><h2 id="阶段-5-模板展开" tabindex="-1">阶段 5：模板展开 <a class="header-anchor" href="#阶段-5-模板展开" aria-label="Permalink to “阶段 5：模板展开”">​</a></h2><ul><li>遇到 <code>{template}</code> 或裸模板标识符时，执行深拷贝替换</li><li>模板内部若包含引用，递归展开（最大递归深度 100）</li></ul><h2 id="阶段-6-实例化与常量折叠" tabindex="-1">阶段 6：实例化与常量折叠 <a class="header-anchor" href="#阶段-6-实例化与常量折叠" aria-label="Permalink to “阶段 6：实例化与常量折叠”">​</a></h2><ul><li>遇到 <code>ClassName { ... }</code> 时，合并属性，绑定继承链</li><li>计算属性按依赖顺序求值</li><li><code>.method()</code> 调用立即执行，结果替换为字面量</li><li><code>std.*</code> 函数计算结果直接替换原 AST 节点</li><li><code>$var</code> 参数替换为传递的值</li></ul><h2 id="最终产物" tabindex="-1">最终产物 <a class="header-anchor" href="#最终产物" aria-label="Permalink to “最终产物”">​</a></h2><p>完全展开、所有逻辑均已消除的<strong>纯 JSON 数据结构</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark" style="background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee;" tabindex="0"><code><span class="line"><span>BON 源码</span></span>
<span class="line"><span>  → [参数注入]</span></span>
<span class="line"><span>  → [词法/语法分析]</span></span>
<span class="line"><span>  → [导入解析]</span></span>
<span class="line"><span>  → [符号解析]</span></span>
<span class="line"><span>  → [控制流展开]  ← if/for 在此阶段处理</span></span>
<span class="line"><span>  → [模板展开]</span></span>
<span class="line"><span>  → [实例化与常量折叠]</span></span>
<span class="line"><span>  → 纯 JSON</span></span>
<span class="line"><span></span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>BON 是<strong>编译期</strong>语言，所有逻辑在解析时完成。宿主程序拿到的永远是纯 JSON，不需要运行时依赖。</p><p>无论 BON 源码多么复杂，输出的 JSON 中将<strong>没有任何残留的 <code>$</code>、<code>if</code> 或 <code>for</code> 痕迹</strong>。</p></div>`,21)])])}const u=e(i,[["render",o]]);export{f as __pageData,u as default};
